#!/usr/bin/env sh
# Writes the version module the Kizu compiler prints for `kizu version`:
#
#   scripts/gen-selfhost-version.sh [root]
#
# Run it before checking, testing, or building compiler/. root defaults to the
# repository this script is in. The line names the revision, so it changes
# with every commit and the generated file is not checked in.
#
# KIZU_RELEASE stamps a release label (`v0.7.0`); without it the build names
# itself `devel`. The line is the one internal/version.Format renders, and
# internal/selfhost.WriteVersionSource writes the same file byte for byte.
set -eu

root="${1:-$(cd "$(dirname "$0")/.." && pwd)}"
path="$root/compiler/src/internal/version/version_source.kizu"

# A git hook runs with GIT_DIR set to the repository it was fired for, and
# that would otherwise win over the directory the commands below run in.
unset GIT_DIR GIT_WORK_TREE GIT_INDEX_FILE GIT_COMMON_DIR GIT_OBJECT_DIRECTORY GIT_PREFIX

# The VCS state is read only where Go stamps it into a binary it builds: a
# `.git` directory. A linked worktree has a `.git` file, and `go build` there
# stamps nothing, so the binary names itself `kizu devel`.
detail=''
if [ -d "$root/.git" ]; then
  revision="$(git -C "$root" rev-parse HEAD)"
  # Go records vcs.time as the commit time in UTC.
  at="$(TZ=UTC git -C "$root" show -s --format=%cd \
    --date=format-local:%Y-%m-%dT%H:%M:%SZ HEAD)"
  status="$(git -C "$root" status --porcelain)"
  detail="$(printf '%.12s' "$revision")"
  if [ -n "$at" ]; then detail="$detail, $at"; fi
  if [ -n "$status" ]; then detail="$detail, modified"; fi
fi

line="kizu ${KIZU_RELEASE:-devel}"
if [ -n "$detail" ]; then line="$line ($detail)"; fi

# Kizu reads the bytes between the quotes verbatim, so a text carrying a quote
# or a newline has no literal form; a version line cannot carry one.
newline='
'
case "$line" in
  *'"'* | *"$newline"*) literal='""' ;;
  *) literal="\"$line\"" ;;
esac

# Written whole and moved into place: the test packages that build compiler/
# each write this first and run beside one another, and a reader must never
# see a file one of them is halfway through.
mkdir -p "$(dirname "$path")"
staging="$(mktemp "$(dirname "$path")/version_source.tmp.XXXXXX")"
trap 'rm -f "$staging"' EXIT
cat > "$staging" <<EOF
// Code generated by \`scripts/gen-selfhost-version.sh\`. DO NOT EDIT.

/// Returns the line \`kizu version\` prints, the Go \`version.String\`
/// rendered from the same VCS state at the time this compiler was built.
pub fn version_string() -> []u8 {
    return $literal;
}
EOF
chmod 644 "$staging"
mv -f "$staging" "$path"
trap - EXIT
